package dev.zomboid.mts;
import java.util.*;
public final class Maintenance {
 static String p="minecrafttransportsimulator.";
 public static double impact(double speed){return speed<=3?0:speed<=15?1:Math.min(6,1+(speed-15)*.1);}
 public static double condition(double damage){return Math.max(0,100-damage);}
 static Object variable(Object v,String id){return R.call(v,"getOrCreateVariable","pz_condition_"+id);}
 static double damage(Object v,String id){return R.num(R.get(variable(v,id),"currentValue"));}
 static void add(Object v,String id,double amount){Object variable=variable(v,id);R.call(variable,"setTo",Math.min(100,R.num(R.get(variable,"currentValue"))+amount),true);}
 public static boolean explosion(boolean original,Object v){return original&&!Mechanics.car(v);}
 public static boolean collision(boolean original,Object v,Object box,boolean hit){if(!Mechanics.car(v))return original;if(!original||!hit||R.num(R.get(v,"crashDebounce"))>0)return false;double strength=impact(R.num(R.get(v,"velocity"))*20)*RoadPhysics.factor(v);if(strength<=0)return false;R.set(v,"crashDebounce",60);Object local=R.get(box,"localCenter");boolean front=R.num(R.get(local,"z"))>=0;double side=R.num(R.get(local,"x"));add(v,"chassis",strength*.2);add(v,front?"front":"rear",strength);if(Math.abs(side)>.7){add(v,side>0?"door_left":"door_right",strength*.5);add(v,side>0?"window_left":"window_right",strength*.7);}else if(front){add(v,"hood",strength*.6);add(v,"windshield",strength*.35);}else add(v,"rear_window",strength*.35);Object general=R.get(R.get(v,"definition"),"general"),dv=R.get(v,"damageVar");double max=R.num(R.get(general,"health"));R.call(dv,"setTo",Math.min(max,R.num(R.get(dv,"currentValue"))+max*strength/100),true);if(front)for(Object engine:(Collection<?>)R.get(v,"engines")){double health=R.num(R.get(R.get(R.get(engine,"definition"),"general"),"health"));Object ev=R.get(engine,"damageVar");R.call(ev,"setTo",Math.min(health,R.num(R.get(ev,"currentValue"))+health*strength/100),true);}return false;}
 public static boolean inspect(Object packet,Object entity,Object player){if(!R.yes(R.get(packet,"rightClick")))return false;Object v=entity.getClass().getSimpleName().equals("PartEngine")?R.get(entity,"vehicleOn"):Mechanics.car(entity)?entity:null;if(v==null||!Mechanics.car(v))return false;Object held=R.call(player,"getHeldStack");if(!R.yes(R.call(held,"isEmpty")))return false;boolean engine=entity.getClass().getSimpleName().equals("PartEngine");if(!engine){Object center=R.get(packet,"hitBoxLocalCenter");List<?> groups=(List<?>)R.get(R.get(v,"definition"),"collisionGroups");boolean hood=false,door=false;for(Object g:groups){String text=Objects.toString(R.get(g,"applyAfter"),"").toLowerCase(Locale.ROOT);for(Object c:(List<?>)R.get(g,"collisions"))if(R.yes(R.call(R.get(c,"pos"),"equals",center))){if(text.matches(".*(hood|bonnet|engine).*"))hood=true;else if(text.contains("door"))door=true;}}if(hood||door||R.num(R.get(center,"z"))<1.5)return false;}if(!R.yes(R.get(R.get(v,"lockedVar"),"isActive"))&&!R.yes(R.call(R.get(v,"world"),"isClient")))Inspection.start(v,player);return true;}
 static String row(Object v,String name,String id){return name+": "+Math.round(condition(damage(v,id)))+"%";}
 public static void repairSync(Object v){if(!Mechanics.car(v)||R.yes(R.call(R.get(v,"world"),"isClient")))return;Object previous=R.call(v,"getOrCreateVariable","pz_last_body_damage");double before=R.num(R.get(previous,"currentValue")),now=R.num(R.get(R.get(v,"damageVar"),"currentValue"));if(before>now&&before>0)for(String id:List.of("chassis","front","rear","hood","door_left","door_right","windshield","window_left","window_right","rear_window")){Object var=variable(v,id);R.call(var,"setTo",R.num(R.get(var,"currentValue"))*now/before,true);}if(before!=now)R.call(previous,"setTo",now,false);}
 public static List<String> report(Object v){List<String> out=new ArrayList<>();out.add("Chasis: "+Math.round(Math.min(Mechanics.health(v)*100,condition(damage(v,"chassis"))))+"%");out.add(row(v,"Defensa delantera","front"));out.add(row(v,"Defensa trasera","rear"));out.add(row(v,"Capo","hood"));out.add(row(v,"Puertas izquierdas","door_left"));out.add(row(v,"Puertas derechas","door_right"));out.add(row(v,"Parabrisas","windshield"));out.add(row(v,"Ventanas izquierdas","window_left"));out.add(row(v,"Ventanas derechas","window_right"));out.add(row(v,"Luneta trasera","rear_window"));if("quad".equals(R.get(R.get(v,"definition"),"systemName")))out.removeIf(row->row.startsWith("Puertas")||row.startsWith("Ventanas")||row.startsWith("Parabrisas")||row.startsWith("Luneta")||row.startsWith("Capo"));int n=0;for(Object engine:(Collection<?>)R.get(v,"engines")){double max=R.num(R.get(R.get(R.get(engine,"definition"),"general"),"health")),d=R.num(R.get(R.get(engine,"damageVar"),"currentValue"));out.add("Motor "+(++n)+": "+Math.round(Mechanics.fraction(d,max)*100)+"%");}long wheels=((Collection<?>)R.get(v,"allParts")).stream().filter(a->a.getClass().getSimpleName().equals("PartGroundDevice")).count();out.add("Ruedas instaladas: "+wheels);out.add("Bateria: "+Math.round(R.num(R.call(Mechanics.class,"battery",v))*100)+"%");out.add("Combustible: "+Math.round(R.num(R.call(Mechanics.class,"fuel",v))*100)+"%");out.add("Revisar no consume objetos.");out.add("Reparar: motor apagado + kit.");return out;}
}
